Concatenate the data rows from all non-combined sheets in workbook order into the combined sheet. Map each source column to the combined header by name and write cached plain values starting at A2. Save the modified workbook to OUT.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb["combined"]

def clean(v):
    if isinstance(v, str):
        return v.strip()
    return v

headers = [clean(ws.cell(row=1, column=c).value) for c in range(1, 16)]
source_sheets = [name for name in vals.sheetnames if name != "combined"]

out_row = 2
written = 0

for name in source_sheets:
    src = vals[name]
    src_headers = [clean(src.cell(row=1, column=c).value) for c in range(1, src.max_column + 1)]

    col_map = {}
    for out_col, h in enumerate(headers, start=1):
        if h is not None and h in src_headers:
            col_map[out_col] = src_headers.index(h) + 1
        else:
            col_map[out_col] = None

    for r in range(2, src.max_row + 1):
        row_vals = []
        for out_col in range(1, len(headers) + 1):
            sc = col_map[out_col]
            v = src.cell(row=r, column=sc).value if sc is not None else None
            row_vals.append(clean(v))

        for c, v in enumerate(row_vals, start=1):
            ws.cell(row=out_row, column=c).value = v

        out_row += 1
        written += 1

        if written <= 3 or written % 100 == 0:
            print(name, r, row_vals[:4])

print("written", written, "last_row", out_row - 1)
wb.save(OUT)
